import { normalizeRelativePath, toPosixPath } from '@mintlify/common';
import type { Warning } from '@mintlify/prebuild';
import { stripVTControlCharacters } from 'node:util';

import type { Finding, Group, Site, SiteRule } from '../types.js';

const FILE = String.raw`[\w@.\\/-]+\.(?:mdx?|jsx?|tsx?|json|ya?ml)\b`;

const FILE_IN_MESSAGE = new RegExp(FILE);

const IMPORTERS = [
  new RegExp(String.raw`\(in (${FILE}),`),
  new RegExp(String.raw`(?:\bin|imported from) (${FILE})`),
];

const IMPORT_TYPES = new Set<Warning['type']>([
  'missing-file',
  'invalid-import-path',
  'import-resolution-error',
  'default-import-no-default-export',
  'export-collision',
  'undeclared-package',
  'package-import-conflict',
]);

const POSITION = /^:(\d+)(?::(\d+))?/;

const QUOTED = /"([^"]+)"/;

const toFinding = (site: Site, warning: Warning): Finding => {
  const clean = stripVTControlCharacters(warning.message).trim();
  const importer =
    warning.file == null && IMPORT_TYPES.has(warning.type)
      ? IMPORTERS.map((pattern) => pattern.exec(clean)?.[1]).find(Boolean)
      : undefined;
  // Missing nav pages are always about the config, even when the page looks like a file
  const match =
    warning.file != null || importer || warning.type === 'missing-nav-page'
      ? null
      : FILE_IN_MESSAGE.exec(clean);
  const found = importer ?? match?.[0];
  const file =
    warning.file ?? (found ? normalizeRelativePath(toPosixPath(found)) : site.configFile);
  const position = match ? POSITION.exec(clean.slice(match.index + match[0].length)) : null;
  // Config warnings quote the entry they're about, such as a navigation page
  const quoted =
    warning.file == null && file === site.configFile ? QUOTED.exec(clean)?.[0] : undefined;
  const located =
    warning.ref != null && warning.line == null
      ? site.locate(file, JSON.stringify(warning.ref))
      : quoted
        ? site.locate(file, quoted)
        : undefined;
  return {
    file,
    ...(warning.line != null
      ? { line: warning.line, ...(warning.column != null && { column: warning.column }) }
      : position && {
          line: Number(position[1]),
          ...(position[2] && { column: Number(position[2]) }),
        }),
    ...located,
    message: clean,
  };
};

/** Warning types some rule turns into diagnostics, so a strict-build failure is explained. */
const COVERED_TYPES = new Set<Warning['type']>(['parse-error']);

const buildRule = (
  id: string,
  group: Group,
  types: Warning['type'][],
  description: string
): SiteRule => {
  for (const type of types) COVERED_TYPES.add(type);
  return {
    id,
    group,
    severity: 'error',
    needsBuild: true,
    scope: 'site',
    description,
    check: (site) =>
      (site.build?.warnings ?? [])
        .filter(({ type }) => types.includes(type))
        .map((warning) => toFinding(site, warning)),
  };
};

export const BUILD_RULES: SiteRule[] = [
  buildRule(
    'missing-nav-page',
    'nav',
    ['missing-nav-page'],
    'pages in the navigation that have no file'
  ),
  buildRule('missing-file', 'content', ['missing-file'], "imported files that don't exist"),
  buildRule(
    'import-error',
    'content',
    [
      'invalid-import-path',
      'import-resolution-error',
      'default-import-no-default-export',
      'export-collision',
    ],
    "imports in pages and snippets that don't resolve"
  ),
  buildRule(
    'package-import',
    'config',
    ['undeclared-package', 'package-import-conflict'],
    'npm package imports that are undeclared or conflict'
  ),
  buildRule('openapi-build', 'openapi', ['openapi'], 'OpenAPI pages the build could not generate'),
  {
    id: 'build-failed',
    group: 'config',
    severity: 'error',
    needsBuild: true,
    scope: 'site',
    description: 'the strict build failed for a reason no rule reports',
    check: (site) => {
      if (!site.build || site.build.passed) return [];
      const unreported = (warning: Warning) =>
        warning.type === 'parse-error' &&
        site.selected !== undefined &&
        !site.selected.has(toFinding(site, warning).file);
      const uncovered = site.build.warnings.filter(
        (warning) => !COVERED_TYPES.has(warning.type) || unreported(warning)
      );
      const findings = uncovered.map((warning) => toFinding(site, warning));
      // Covered warnings are the selected rules' to report; disabled ones are meant to pass
      return site.build.strict
        ? findings
        : [...findings, { file: site.configFile, message: site.build.error }];
    },
  },
];

/** Build warnings of one type, which the engine merges into the static rule that covers them. */
export const buildFindings = (site: Site, type: Warning['type']): Finding[] =>
  (site.build?.warnings ?? [])
    .filter((warning) => warning.type === type)
    .map((warning) => toFinding(site, warning));
